/**
 * Tidigmodern tid (0.36, Historiska epoker → Tidigmodern tid, modules 1931–1937): renaissance and
 * humanism, the reformation, voyages of discovery, colonial empires, absolutism and court life, the
 * scientific revolution and the trade routes of Europe.
 * Recurring signs: people in period clothes (velvet, ruffs, white wigs at court), a domed city, a
 * church with a cross, sailing ships on blue waves, gold for crowns and riches, a parchment map with a
 * dashed route, and a night sky for astronomy. No words in the pictures (only digits), no brands and
 * no pointing fingers. Abstract words get a small symbolic scene with a grey reference where a
 * contrast helps.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { HL, arm, bubble, heart, note, thought } from './people';
import { P as F, type Mood, greyed, coin } from './blindFix';

// ── Palette and geometry ─────────────────────────────────────────────
const GOLD = '#e0b03a';
const GOLD2 = '#b8862a';
const VELVET = '#7a2a4a';
const ROYAL = '#4a3a9a';
const RED = '#d23a32';
const WOOD = '#a0673d';
const WOOD2 = '#7a4a28';
const SEA = '#8cc8ea';
const SEA2 = '#4f94c4';
const SAIL = '#f6efdc';
const PAPER = '#f3e6c4';
