const f1 = (n: number) => +n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
const field = (y = 100, col = GRASS) => rect(4, y, 112, 112 - y, col, 0, null);
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, ty, hy: f1(ty - 56 * s), sy: f1(ty - 38 * s), sl: f1(x - 13 * s), sr: f1(x + 13 * s) }; };
/** An arm from the shoulder (side −1 = picture-left, 1 = picture-right) to a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q = geo(x, h); return all(arm(side < 0 ? q.sl : q.sr, q.sy, tx, ty), circle(tx, ty, f1(3 * Math.max(0.6, h)), C.skin, C.ink, 1.2)); };
/** Draw in the local coordinates of the standing figure at x (head centre 0,−56). */
const on = (x: number, h: number, ...k: Svg[]) => { const s = 0.84 * h; return g(`translate(${x} ${f1(112 - 49 * s)}) scale(${s.toFixed(3)})`, ...k); };
/** A person (F = mood figure) with optional extra drawn in local coordinates. */
const who = (x: number, top: string, bottom: string, mood: Mood = 'smile', more: Partial<Build> = {}) => F({ x, top, bottom, mood, ...more });
/** A curly white court wig. */
const wig = (x: number, h = 1) => on(x, h, ...[[-10, -60], [-12, -51], [-11, -42], [10, -60], [12, -51], [11, -42], [0, -67], [-6, -66], [6, -66]].map(([a, b]) => circle(a!, b!, 5, WIG, C.ink, 1.1)), circle(0, -54, 7.6, C.skin, null), circle(-3.4, -56, 1.2, C.ink, null), circle(3.4, -56, 1.2, C.ink, null), path('M-3 -51.5 Q0 -49 3 -51.5', 'none', C.ink, 1.3));
const crown = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-9 0 L-10 -10 L-5 -5 L0 -12 L5 -5 L10 -10 L9 0 Z', GOLD, C.ink, 1.2), circle(0, -3, 1.5, RED, null));
const crownOn = (x: number, h = 1) => on(x, h, crown(0, -64, 1));
/** A flat black or coloured hat (scholar's beret). */
const beret = (x: number, h = 1, col = BLACK) => on(x, h, ellipse(0, -65, 12, 4, col, C.ink, 1.2));
/** A long robe over the legs. */
const robe = (x: number, h = 1, col = BLACK) => on(x, h, path('M-14 -42 L14 -42 L17 49 L-17 49 Z', col, C.ink, 1.6), circle(0, -56, 10, C.skin, C.ink, 2));
const cross = (x: number, y: number, s = 1, col = GOLD) => g(`translate(${x} ${y}) scale(${s})`, rect(-1.6, -8, 3.2, 16, col, 0.5, C.ink, 0.9), rect(-5.5, -4, 11, 3.2, col, 0.5, C.ink, 0.9));
const xMark = (x: number, y: number, s = 1, col = RED) => line(`M${f1(x - 5 * s)} ${f1(y - 5 * s)} L${f1(x + 5 * s)} ${f1(y + 5 * s)} M${f1(x + 5 * s)} ${f1(y - 5 * s)} L${f1(x - 5 * s)} ${f1(y + 5 * s)}`, col, f1(2.4 * s));
const okC = (x: number, y: number, r = 7) => all(circle(x, y, r, GOOD, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, f1(r * 0.24)));
const ban = (x: number, y: number, r = 10, w = 2.6) => all(circle(x, y, r, 'none', RED, w), line(`M${f1(x - r * 0.7)} ${f1(y + r * 0.7)} L${f1(x + r * 0.7)} ${f1(y - r * 0.7)}`, RED, w));
const dash = (d: string, col: string = HL, w = 1.6, da = '3 3') => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-dasharray="${da}" stroke-linecap="round"/>`;
const wavesL = (y: number, x1 = 6, x2 = 114, col = SEA2) => { let d = `M${x1} ${y}`; for (let x = x1; x < x2; x += 10) d += ` q2.5 -3 5 0 q2.5 3 5 0`; return line(d, col, 1.3); };
const sea = (y = 92) => all(rect(4, y, 112, 112 - y, SEA, 0, null), wavesL(y + 6), wavesL(y + 13, 12));
const sky = (col = '#e6f2fa', y2 = 112) => rect(4, 4, 112, y2 - 4, col, 0, null);
const nightSky = () => all(rect(4, 4, 112, 108, NIGHT, 0, null), ...[[14, 14], [30, 30], [52, 12], [76, 24], [98, 14], [108, 40], [20, 50], [88, 50]].map(([a, b]) => circle(a!, b!, 1.2, C.white, null)));

