const book = (x: number, y: number, s = 1, col = '#7a3a2a', lines = true) => g(`translate(${x} ${y}) scale(${s})`, path('M-14 -2 L0 0 L14 -2 L14 -16 L0 -14 L-14 -16 Z', col, C.ink, 1.2), path('M-12 -3 L0 -1.6 L12 -3 L12 -15 L0 -13 L-12 -15 Z', PAPER, C.ink, 0.9), line('M0 -13 L0 -1.6', C.ink, 0.9), lines ? line('M-10 -12 L-3 -11 M-10 -9 L-3 -8 M-10 -6 L-3 -5 M3 -11 L10 -12 M3 -8 L10 -9 M3 -5 L10 -6', C.grey, 0.8) : '');
const closedBook = (x: number, y: number, s = 1, col = '#7a3a2a') => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -14, 20, 28, col, 2, C.ink, 1.4), rect(8, -12, 2, 24, PAPER, 0, null), cross(0, -2, 0.7));
const scroll = (x: number, y: number, s = 1, rot = 0, lines = true) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-10, -14, 20, 28, PAPER, 1, C.ink, 1.2), ellipse(0, -14, 11, 2.6, '#e2d0a2', C.ink, 1), ellipse(0, 14, 11, 2.6, '#e2d0a2', C.ink, 1), lines ? line('M-6 -8 L6 -8 M-6 -4 L6 -4 M-6 0 L6 0 M-6 4 L4 4 M-6 8 L2 8', C.grey, 0.9) : '');
