const bag = (x: number, y: number, s = 1, col = '#c9a06a') => g(`translate(${x} ${y}) scale(${s})`, path('M-10 0 C-14 -6 -12 -16 -4 -18 L4 -18 C12 -16 14 -6 10 0 Z', col, C.ink, 1.4), line('M-5 -18 L5 -18', C.ink, 2), circle(0, -8, 3.4, GOLD, C.ink, 0.8));
